"""Turn an evaluation report into demo/data.js for the static demo page.

The page shows recorded traces from a real run; it does not call the server. Volatile values (durations) are
dropped so the file is reproducible and a drift test can compare it with a fresh run.
"""

from __future__ import annotations

import json
from typing import Any

HEADER = (
    "// Generated by `ledger-assistant build-demo` from a real evaluation run over Streamable HTTP.\n"
    "// Demo Mode: deterministic rule-based planner, no LLM. Do not edit by hand.\n"
)


def _step(step: dict[str, Any]) -> dict[str, Any]:
    if step["kind"] == "turn":
        trace = step["trace"]
        return {
            "kind": "turn",
            "question": trace["question"],
            "planner": trace["planner"],
            "plan": trace["plan"],
            "outcome": trace["outcome"],
            "answer": trace["answer"],
            "notes": trace["notes"],
            "evidence": trace["evidence"],
            "checks": step["checks"],
            "findings": step["findings"],
        }
    return {
        "kind": step["kind"],
        "question": None,
        "planner": None,
        "plan": {"kind": "tool_call", "tool": step["tool"], "arguments": step["arguments"],
                 "rationale": "Direct tool call that bypasses the planner, simulating a misbehaving agent."},
        "outcome": step["outcome"],
        "answer": None,
        "notes": [],
        "evidence": [],
        "checks": step["checks"],
        "findings": step["findings"],
    }


def render_demo_data(report: dict[str, Any]) -> str:
    payload = {
        "planner": report["planner"],
        "mode": report["mode"],
        "uses_llm": report["uses_llm"],
        "grader": report["grader"],
        "dataset_as_of": report["dataset_as_of"],
        "case_count": report["case_count"],
        "cases_passed": report["cases_passed"],
        "scope_leaks": report["scope_leaks"],
        "metrics": report["metrics"],
        "cases": [
            {"id": c["id"], "category": c["category"], "principal": c["principal"], "passed": c["passed"],
             "steps": [_step(s) for s in c["steps"]]}
            for c in report["cases"]
        ],
    }
    return HEADER + "window.LEDGER_DEMO = " + json.dumps(payload, indent=1) + ";\n"
